p = '_data/catalogo.json'
d = json.load(io.open(p, encoding='utf-8')); n = 0
for x in d['prodotti']:
    if x['id'] not in D: continue
    ii, ui, ie, ue = D[x['id']]
    x['descrizione_completa'] = "%s\n\n## Come usarlo\n\n%s\n\n## Conservazione\n\n%s" % (ii, ui, CI)
    x['tr']['en']['descrizione_completa'] = "%s\n\n## How to use\n\n%s\n\n## Storage\n\n%s" % (ie, ue, CE)
    n += 1
io.open(p, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=2))
print('ok', n, 'prodotti su', len(d['prodotti']))
